def _decode_jpeg(value: str) -> bytes:
    if not isinstance(value, str) or "," not in value:
        raise ValueError("原始图片格式无效，请重新截取当前摄像头画面")
    header, encoded = value.split(",", 1)
    if header.lower() not in {"data:image/jpeg;base64", "data:image/jpg;base64"}:
        raise ValueError("只允许保存 JPEG 原始图片")
    try:
        return base64.b64decode(encoded, validate=True)
    except Exception as exc:
        raise ValueError("原始图片编码损坏，请重新保存") from exc


def _phash(image: Image.Image) -> str:
    pixels = np.asarray(
        image.convert("L").resize((32, 32), Image.Resampling.LANCZOS),
        dtype=np.float64,
    )
    n = 32
    x = np.arange(n)
    basis = np.cos((2 * x[:, None] + 1) * x[None, :] * np.pi / (2 * n))
    basis[:, 0] /= np.sqrt(2)
    low = ((2 / n) * basis.T @ pixels @ basis)[:8, :8].reshape(-1)
    bits = low > float(np.median(low[1:]))
    return f"{int(''.join('1' if bit else '0' for bit in bits), 2):016x}"


def _hamming(left: str, right: str) -> int:
    return (int(left, 16) ^ int(right, 16)).bit_count()


def _sharpness(image: Image.Image) -> float:
    gray = np.asarray(image.convert("L").resize((320, 180)), dtype=np.float32)
    laplacian = (
        -4 * gray[1:-1, 1:-1]
        + gray[:-2, 1:-1]
        + gray[2:, 1:-1]
        + gray[1:-1, :-2]
        + gray[1:-1, 2:]
    )
    return float(np.var(laplacian))


def _bbox(value: Any, width: int, height: int) -> list[float] | None:
    if value is None:
        return None
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError("设备框格式错误，应为 [x1, y1, x2, y2]")
    x1, y1, x2, y2 = map(float, value)
    if not (0 <= x1 < x2 <= width and 0 <= y1 < y2 <= height):
        raise ValueError("设备框超出图片范围，请重新画框")
    if x2 - x1 < 4 or y2 - y1 < 4:
        raise ValueError("设备框过小，请重新画框")
    return [x1, y1, x2, y2]


