const content=`from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from src.active_learning_capture import ActiveLearningCaptureStore

LEGACY_TARGET_ID = "legacy_device_v1"
NEW_TARGET_ID = "new_target_v1"
DEFAULT_TARGET_ID = NEW_TARGET_ID


@dataclass(frozen=True)
class TargetSpec:
    target_object_id: str
    target_object_version: str
    label_zh: str
    data_root: Path
    read_only: bool
    split_policy: str

    def as_dict(self) -> dict[str, Any]:
        return {
            "target_object_id": self.target_object_id,
            "target_object_version": self.target_object_version,
            "label_zh": self.label_zh,
            "data_root": str(self.data_root),
            "read_only": self.read_only,
            "split_policy": self.split_policy,
        }


class TargetCaptureRegistry:
    """Keep legacy and replacement-object capture data physically isolated."""

    def __init__(self, legacy_root: Path, new_target_root: Path):
        self.specs = {
            LEGACY_TARGET_ID: TargetSpec(
                LEGACY_TARGET_ID, "1", "历史医美设备（只读）",
                legacy_root, True, "legacy_existing_split",
            ),
            NEW_TARGET_ID: TargetSpec(
                NEW_TARGET_ID, "1", "新物品 V1（采集中）",
                new_target_root, False, "subject_and_session_grouped_later",
            ),
        }
        self.stores = {
            LEGACY_TARGET_ID: ActiveLearningCaptureStore(
                legacy_root, target_object_id=LEGACY_TARGET_ID,
            ),
            NEW_TARGET_ID: ActiveLearningCaptureStore(
                new_target_root,
                target_object_id=NEW_TARGET_ID,
                auto_split_pattern=("train",),
            ),
        }
        self.active_target_id: str | None = None
        self._write_context(NEW_TARGET_ID)

    def _write_context(self, target_object_id: str) -> None:
        spec = self.specs[target_object_id]
        path = spec.data_root / "target_context.json"
        if path.exists():
            return
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(
                {
                    **spec.as_dict(),
                    "production_ready": False,
                    "legacy_predictions_are_training_labels": False,
                },
                ensure_ascii=False,
                indent=2,
            ) + "\\n",
            encoding="utf-8",
        )

    def _target_id(self, value: str | None, *, default: str = DEFAULT_TARGET_ID) -> str:
        target = str(value or default).strip()
        if target not in self.stores:
            raise ValueError(f"不支持的目标版本：{target}")
        return target

    def _store(self, value: str | None) -> ActiveLearningCaptureStore:
        return self.stores[self._target_id(value)]

    def _decorate(self, payload: dict[str, Any], target: str) -> dict[str, Any]:
        result = dict(payload)
        result["target_object_id"] = target
        result["target_object_version"] = self.specs[target].target_object_version
        if isinstance(result.get("sample"), dict):
            result["sample"] = {**result["sample"], "target_object_id": target}
        if isinstance(result.get("items"), list):
            result["items"] = [
                {**item, "target_object_id": target} for item in result["items"]
            ]
        return result

    def list_targets(self) -> dict[str, Any]:
        return {
            "default_target_object_id": DEFAULT_TARGET_ID,
            "targets": [spec.as_dict() for spec in self.specs.values()],
        }

    def start_session(self, metadata: dict[str, Any]) -> dict[str, Any]:
        target = self._target_id(metadata.get("target_object_id"))
        if self.specs[target].read_only:
            raise ValueError("历史旧设备数据已经冻结，只允许查看，不能继续采集")
        if self.active_target_id and self.active_target_id != target:
            raise RuntimeError(
                f"当前已有 {self.active_target_id} 采集 Session，请先停止"
            )
        result = self.stores[target].start_session(metadata)
        self.active_target_id = target
        return self._decorate(result, target)

    def stop_session(self) -> dict[str, Any]:
        target = self.active_target_id or DEFAULT_TARGET_ID
        result = self.stores[target].stop_session()
        self.active_target_id = None
        return self._decorate(result, target)

    def _active_store(
        self, payload: dict[str, Any] | None = None
    ) -> tuple[str, ActiveLearningCaptureStore]:
        target = self._target_id(
            (payload or {}).get("target_object_id"),
            default=self.active_target_id or DEFAULT_TARGET_ID,
        )
        if target != self.active_target_id:
            raise RuntimeError("采集目标与当前 Session 不一致，请新建 Session")
        return target, self.stores[target]

    def quick_save(self, payload: dict[str, Any], status: str) -> dict[str, Any]:
        target, store = self._active_store(payload)
        payload = dict(payload)
        if target == NEW_TARGET_ID:
            intended = str(payload.get("intended_contact_state", "touching"))
            payload["bbox"] = None
            payload["contact_point"] = None
            payload["contact_visibility"] = (
                "not_in_contact" if intended == "not_in_contact"
                else "not_annotatable"
            )
            snapshot = dict(payload.get("prediction_snapshot") or {})
            snapshot["training_label_eligible"] = False
            snapshot["reason"] = "legacy model prediction is not valid for new target"
            payload["prediction_snapshot"] = snapshot
        return self._decorate(store.quick_save(payload, status), target)

    def save_video(self, raw: bytes, metadata: dict[str, Any]) -> dict[str, Any]:
        target, store = self._active_store(metadata)
        return self._decorate(store.save_video(raw, metadata), target)

    def save_confirmed(self, payload: dict[str, Any]) -> dict[str, Any]:
        target, store = self._active_store(payload)
        return self._decorate(store.save_confirmed(payload), target)

    def status(self, target_object_id: str | None = None) -> dict[str, Any]:
        if target_object_id == "all":
            return {
                **self.list_targets(),
                "active_target_object_id": self.active_target_id,
                "by_target": {
                    target: self._decorate(store.status(), target)
                    for target, store in self.stores.items()
                },
            }
        target = self._target_id(
            target_object_id,
            default=self.active_target_id or DEFAULT_TARGET_ID,
        )
        return self._decorate(self.stores[target].status(), target)

    def list_subjects(self, target_object_id: str | None = None) -> dict[str, Any]:
        target = self._target_id(target_object_id)
        return self._decorate(self.stores[target].list_subjects(), target)

    def register_subject(
        self, value: str, target_object_id: str | None = None
    ) -> dict[str, Any]:
        target = self._target_id(target_object_id)
        if self.specs[target].read_only:
            raise ValueError("历史旧设备人物库已经冻结")
        return self._decorate(self.stores[target].register_subject(value), target)

    def list_samples(
        self, *, target_object_id: str | None = None, **kwargs: Any
    ) -> dict[str, Any]:
        target = self._target_id(target_object_id)
        return self._decorate(self.stores[target].list_samples(**kwargs), target)

    def _locate(
        self, sample_id: str, target_object_id: str | None = None
    ) -> tuple[str, ActiveLearningCaptureStore]:
        if target_object_id:
            target = self._target_id(target_object_id)
            self.stores[target].sample_detail(sample_id)
            return target, self.stores[target]
        for target, store in self.stores.items():
            try:
                store.sample_detail(sample_id)
                return target, store
            except KeyError:
                continue
        raise KeyError(sample_id)

    def sample_detail(
        self, sample_id: str, target_object_id: str | None = None
    ) -> dict[str, Any]:
        target, store = self._locate(sample_id, target_object_id)
        return self._decorate(store.sample_detail(sample_id), target)

    def image_path(self, sample_id: str, target_object_id: str | None = None) -> Path:
        return self._locate(sample_id, target_object_id)[1].image_path(sample_id)

    def preview_path(self, sample_id: str, target_object_id: str | None = None) -> Path:
        return self._locate(sample_id, target_object_id)[1].preview_path(sample_id)

    def review(
        self, sample_id: str, payload: dict[str, Any],
        target_object_id: str | None = None,
    ) -> dict[str, Any]:
        target, store = self._locate(sample_id, target_object_id)
        if self.specs[target].read_only:
            raise ValueError("历史旧设备标注已经冻结，只允许查看")
        return self._decorate(store.review(sample_id, payload), target)

    def delete(
        self, sample_id: str, target_object_id: str | None = None
    ) -> dict[str, Any]:
        target, store = self._locate(sample_id, target_object_id)
        if self.specs[target].read_only:
            raise ValueError("历史旧设备标注已经冻结，只允许查看")
        return self._decorate(store.delete(sample_id), target)

    def restore(
        self, sample_id: str, target_object_id: str | None = None
    ) -> dict[str, Any]:
        target, store = self._locate(sample_id, target_object_id)
        if self.specs[target].read_only:
            raise ValueError("历史旧设备标注已经冻结，只允许查看")
        return self._decorate(store.restore(sample_id), target)
