class ActiveLearningCaptureStore:
    """Capture pending samples and expose an auditable review workflow."""

    def __init__(
        self,
        root: Path,
        min_interval_ms: int = 400,
        phash_distance: int = 4,
        *,
        target_object_id: str = "legacy_device_v1",
        auto_split_pattern: tuple[str, ...] = AUTO_SPLIT_PATTERN,
        seed_subjects: tuple[str, ...] = ("贝塔", "凌川", "帕斯卡", "布尔"),
    ):
        if not auto_split_pattern or any(
            split not in {"train", "val", "test"} for split in auto_split_pattern
        ):
            raise ValueError("自动划分规则只能包含 train/val/test")
        self.root = root
        self.target_object_id = target_object_id
        self.auto_split_pattern = tuple(auto_split_pattern)
        self.seed_subjects = tuple(seed_subjects)
        self.data_root = root / "sessions"
        self.subject_view_root = root / "by_subject"
        self.manifest_root = root / "manifests"
        self.min_interval_ms = min_interval_ms
        self.phash_distance = phash_distance
        self._lock = threading.RLock()
        self._active: ActiveSession | None = None
        self._last_timestamp_ms: int | None = None
        root.mkdir(parents=True, exist_ok=True)
        self._migrate_manifest()

    @property
    def manifest_path(self) -> Path:
        return self.manifest_root / "samples.csv"

    @property
    def dataset_split_path(self) -> Path:
        return self.manifest_root / "dataset_split_v1.csv"

    @property
        split_map = self._dataset_split_map()
        rows = [self._public_row(row, split_map) for row in self._rows()]
        counts = {
            split: {
                "device": 0,
                "no_device": 0,
                "total": 0,
                "pending_review": 0,
                "confirmed": 0,
                "deleted": 0,
            }
            for split in SPLITS
        }
        for row in rows:
            split = row.get("split", "")
            if split not in counts:
                continue
            state = row.get("review_state") or row.get("annotation_state") or "confirmed"
            if state in REVIEW_STATES:
                counts[split][state] += 1
            if state == "confirmed" and row.get("status") in {"device", "no_device"}:
                counts[split][row["status"]] += 1
                counts[split]["total"] += 1
        targets = {
            "train": {"device": 90, "no_device": 1},
            "val": {"device": 0, "no_device": 0},
            "test": {"device": 0, "no_device": 0},
        }
        remaining = {
            split: {
                label: max(0, target - counts[split][label])
                for label, target in values.items()
            }
            for split, values in targets.items()
        }
        return {
            "target_object_id": self.target_object_id,
            "split_policy": list(self.auto_split_pattern),
            "active_session": asdict(self._active) if self._active else None,
            "counts": counts,
            "targets": targets,
            "remaining": remaining,
            "training_ready": all(
                value == 0 for values in remaining.values() for value in values.values()
            ),
            "root": str(self.root),
        }
